MODEL_TEXT = '"""In-memory FOIMS-X sandbox; no native calls, persistence, or catalog writes."""\nfrom copy import deepcopy\nfrom datetime import datetime, timedelta\nimport math\nimport time\n\nEPOCH = datetime(1992, 2, 1)\n\nclass FoimsXSandbox:\n    def __init__(self, tables, clock=time.monotonic):\n        self._clock = clock\n        self.reset(tables)\n\n    def reset(self, tables=None):\n        if tables is not None:\n            self._catalog = deepcopy(tables)\n        self.running = False\n        self._minutes = 0.0\n        self._last_real = self._clock()\n        self.activity = []\n        self.metrics = {}\n        for row in self._catalog.get("metrics", []):\n            if str(row.get("active", "true")).strip().lower() == "false":\n                continue\n            self.metrics[row["metric_id"]] = float(row["default_value"])\n        start = 900\n        for row in self._catalog.get("territory_settings", []):\n            if row.get("setting_id") == "STARTING_EVIDENCE" and str(row.get("active", "false")).lower() == "true":\n                start = int(row["value"])\n        if start < 0:\n            raise ValueError("starting Evidence cannot be negative")\n        self.available_evidence = start\n        self.lifetime_evidence = start\n        self.department_funding = None\n\n    def metric_rows(self):\n        return [deepcopy(row) for row in self._catalog.get("metrics", [])\n                if row.get("metric_id") in self.metrics]\n\n    def set_metric(self, metric_id, value):\n        if metric_id not in self.metrics:\n            raise ValueError("Select a known active metric")\n        if isinstance(value, bool):\n            raise ValueError("Metric value must be a whole number")\n        from decimal import Decimal, InvalidOperation\n        try:\n            number = Decimal(str(value).strip())\n        except (InvalidOperation, ValueError):\n            raise ValueError("Metric value must be a whole number") from None\n        if not number.is_finite() or number != number.to_integral_value():\n            raise ValueError("Metric value must be a finite whole number")\n        row = next(r for r in self.metric_rows() if r["metric_id"] == metric_id)\n        minimum = Decimal(str(row["internal_min"]))\n        maximum = Decimal(str(row["internal_max"]))\n        if not minimum.is_finite() or not maximum.is_finite() or maximum < minimum:\n            raise ValueError("Metric catalog has invalid bounds")\n        if not minimum <= number <= maximum:\n            raise ValueError(f"Value must be between {minimum} and {maximum}")\n        before = self.metrics[metric_id]\n        after = int(number)\n        if before == after:\n            return False\n        self._settle()\n        self.metrics[metric_id] = after\n        state = self.snapshot()\n        self.activity.append({"strategic_minutes": state["strategic_minutes"],\n                              "timestamp": state["date"] + " " + state["time"],\n                              "metric_id": metric_id, "before": before, "after": after})\n        self.activity = self.activity[-200:]\n        return True\n\n    def _settle(self):\n        now = self._clock()\n        if self.running:\n            self._minutes += max(0.0, now - self._last_real)\n        self._last_real = now\n\n    def play(self):\n        self._settle()\n        self.running = True\n\n    def pause(self):\n        self._settle()\n        self.running = False\n\n    def tick(self):\n        self._settle()\n\n    def step(self, minutes):\n        if self.running:\n            raise ValueError("pause before stepping")\n        if type(minutes) is not int or minutes <= 0:\n            raise ValueError("step must be a positive whole number of minutes")\n        self._minutes += minutes\n\n    def snapshot(self):\n        minutes = int(self._minutes)\n        dt = EPOCH + timedelta(minutes=minutes)\n        return {"running": self.running, "strategic_minutes": minutes,\n                "date": dt.strftime("%Y-%m-%d"), "time": dt.strftime("%H:%M:%S"),\n                "day": minutes // 1440 + 1, "cycle_percent": minutes % 1440 / 1440 * 100,\n                "metrics": dict(self.metrics), "activity": deepcopy(self.activity), "available_evidence": self.available_evidence,\n                "lifetime_evidence": self.lifetime_evidence,\n                "department_funding": self.department_funding}\n'
TEST_TEXT = 'import sys\nimport unittest\nfrom copy import deepcopy\nfrom pathlib import Path\nsys.path.insert(0, str(Path(__file__).resolve().parents[1]))\nfrom doda_foims_x_sandbox import FoimsXSandbox\nimport ast\nimport math\nsource = (Path(__file__).resolve().parents[1] / "doda_foims_x_preview.py").read_text(encoding="utf-8-sig")\nparsed = ast.parse(source)\nnumber = next(n for n in parsed.body if isinstance(n, ast.FunctionDef) and n.name == "numeric_value")\nklass = next(n for n in parsed.body if isinstance(n, ast.ClassDef) and n.name == "FoimsXPreview")\nklass.body = [n for n in klass.body if isinstance(n, ast.FunctionDef) and n.name in ("_visible_metric_rows", "_tier_for_value")]\nsubset = ast.Module(body=[number, klass], type_ignores=[])\nexec(compile(subset, "preview_projection_methods", "exec"), globals())\n\nclass Clock:\n    def __init__(self): self.now = 0.0\n    def __call__(self): return self.now\nclass Variable:\n    def __init__(self, value=""): self.value = value\n    def get(self): return self.value\n    def set(self, value): self.value = value\n\nclass FoimsXMetricActivityTests(unittest.TestCase):\n    def setUp(self):\n        self.clock = Clock()\n        self.tables = {"metrics": [{"metric_id": "M"+str(i), "display_name": "Metric "+str(i),\n                                   "default_value": "300", "internal_min": "0", "internal_max": "1000",\n                                   "active": "true"} for i in range(5)]}\n        self.tables["metrics"].append({"metric_id": "OFF", "default_value": "10", "active": "false"})\n        self.model = FoimsXSandbox(self.tables, self.clock)\n    def test_valid_metric_change(self):\n        self.assertTrue(self.model.set_metric("M0", "600"))\n        self.assertEqual(self.model.metrics["M0"], 600)\n    def test_inclusive_bounds(self):\n        self.model.set_metric("M0", 0); self.model.set_metric("M0", 1000)\n        self.assertEqual(self.model.metrics["M0"], 1000)\n    def test_bad_values_are_atomic(self):\n        baseline = self.model.snapshot()\n        for value in (-1, 1001, "abc", "NaN", "Infinity", 1.5, True, ""):\n            with self.subTest(value=value):\n                with self.assertRaises(ValueError): self.model.set_metric("M0", value)\n                self.assertEqual(self.model.snapshot(), baseline)\n    def test_unknown_and_inactive_rejected(self):\n        for metric in ("UNKNOWN", "OFF"):\n            with self.assertRaises(ValueError): self.model.set_metric(metric, 5)\n    def test_timestamp_and_before_after(self):\n        self.model.step(60); self.model.set_metric("M0", 500)\n        self.assertEqual(self.model.snapshot()["activity"], [{"strategic_minutes": 60,\n            "timestamp": "1992-02-01 01:00:00", "metric_id": "M0", "before": 300.0, "after": 500}])\n    def test_running_action_settles_time(self):\n        self.model.play(); self.clock.now = 12\n        self.model.set_metric("M0", 400)\n        self.assertEqual(self.model.snapshot()["activity"][0]["strategic_minutes"], 12)\n        self.assertTrue(self.model.running)\n    def test_noop_does_not_log(self):\n        self.assertFalse(self.model.set_metric("M0", 300))\n        self.assertEqual(self.model.activity, [])\n    def test_reset_clears_history(self):\n        self.model.set_metric("M0", 500); self.model.reset()\n        self.assertEqual(self.model.activity, [])\n        self.assertEqual(self.model.metrics["M0"], 300)\n    def test_catalog_and_snapshot_detached(self):\n        baseline = deepcopy(self.tables)\n        self.model.set_metric("M0", 500)\n        self.model.metric_rows()[0]["display_name"] = "Changed"\n        self.model.snapshot()["activity"][0]["after"] = 12\n        self.assertEqual(self.tables, baseline)\n        self.assertEqual(self.model.snapshot()["activity"][0]["after"], 500)\n    def test_activity_history_is_bounded(self):\n        for i in range(205): self.model.set_metric("M0", i)\n        self.assertEqual(len(self.model.activity), 200)\n        self.assertEqual(self.model.activity[-1]["after"], 204)\n    def test_each_metric_can_be_shown_first(self):\n        preview = FoimsXPreview.__new__(FoimsXPreview)\n        preview.sandbox = self.model; preview.selected_metric = Variable()\n        for i in range(5):\n            preview.selected_metric.set("M"+str(i))\n            self.assertEqual(preview._visible_metric_rows()[0]["metric_id"], "M"+str(i))\n            self.assertEqual(len(preview._visible_metric_rows()), 3)\n    def test_tier_projection_changes_at_boundaries(self):\n        tiers = [{"metric_id": "M0", "min_inclusive": "0", "max_inclusive": "200", "tier_id": "LOW"},\n                 {"metric_id": "M0", "min_inclusive": "201", "max_inclusive": "1000", "tier_id": "HIGH"}]\n        for value, tier_id in ((200,"LOW"), (201,"HIGH"), (1000,"HIGH")):\n            self.model.set_metric("M0", value)\n            self.assertEqual(FoimsXPreview._tier_for_value("M0", self.model.metrics["M0"], tiers)["tier_id"], tier_id)\n\nif __name__ == "__main__": unittest.main()\n'
EXPECTED_MODEL_AST_SHA256 = '2738624083d8ef68688bf8f8bc39d81270f145d9aafe076cc12f19810efaf297'

import argparse
import ast
import hashlib
import re
import subprocess
import sys
from datetime import datetime
from pathlib import Path

parser = argparse.ArgumentParser(description="Install FOIMS-X metric controls and session activity log")
parser.add_argument("--root", type=Path, required=True)
root = parser.parse_args().root.resolve()
work = root / "tools/doda_content_workbench"
preview = work / "doda_foims_x_preview.py"
model = work / "doda_foims_x_sandbox.py"
test = work / "tests/test_foims_x_metric_activity.py"
history = root / "docs/workbench/history/FOIMSX_Metric_Activity_2026-10-09.md"

def stop(message):
    raise SystemExit("STOP: " + message + " No project files were modified.")
for path in (preview, model):
    if not path.is_file(): stop(str(path) + " is missing; install the sandbox foundation first.")
for path in (test, history):
    if path.exists(): stop(str(path) + " already exists. Do not rerun an applied patch.")
    if not path.parent.is_dir(): stop("Missing directory: " + str(path.parent))
raw_preview = preview.read_bytes()
raw_model = model.read_bytes()
text = raw_preview.decode("utf-8-sig").replace("\r\n", "\n")
model_source = raw_model.decode("utf-8-sig")
if hashlib.sha256(ast.dump(ast.parse(model_source), include_attributes=False).encode()).hexdigest() != EXPECTED_MODEL_AST_SHA256:
    stop("The sandbox model differs from the verified foundation. Attach its current source rather than forcing this patch.")
if "self.sandbox = FoimsXSandbox(app.tables)" not in text:
    stop("The preview does not contain the sandbox foundation.")
for old, replacement in PATCH_OPERATIONS:
    if text.count(old) != 1:
        stop("Preview anchor differs: " + old[:100])
    text = text.replace(old, replacement)
for path, body in ((preview, text), (model, MODEL_TEXT), (test, TEST_TEXT)):
    compile(body, str(path), "exec")
backups = work / "backups"
numbers = [int(m.group(1)) for p in backups.iterdir() if p.is_dir() and (m := re.match(r"^v(\d+)_", p.name))] if backups.exists() else []
backup = backups / (f"v{max(numbers, default=72)+1:03d}_foimsx_metric_activity_" + datetime.now().strftime("%Y%m%d_%H%M%S"))
originals = {preview: raw_preview, model: raw_model, test: None, history: None}
manifest = []
for path, raw in originals.items():
    if raw is None: continue
    target = backup / path.relative_to(root)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(raw)
    if target.read_bytes() != raw: stop("Backup verification failed.")
    manifest.append(hashlib.sha256(raw).hexdigest() + "  " + path.relative_to(root).as_posix())
(backup / "MANIFEST.txt").write_text("\n".join(manifest) + "\n", encoding="utf-8")

def encode(body, raw):
    if b"\r\n" in raw: body = body.replace("\n", "\r\n")
    return (b"\xef\xbb\xbf" if raw.startswith(b"\xef\xbb\xbf") else b"") + body.encode()
history_text = """# FOIMS-X Metric Controls And Activity - 2026-10-09

Adds a sandbox-only metric selector and validated whole-number values within
catalog min/max bounds. Selected metric appears first in the three-card panel.
Timestamped metric changes retain the latest 200 entries, with two shown on the
right CRT and a scrollable Activity Log window. Unchanged/invalid values do not
log an event. Reset clears activity and restores metric defaults; refresh does
not reset session state. All metric definitions are copied from the session's
catalog; Reset Session adopts refreshed authoring defaults.
No CSV writes, native calls, game changes, economy or automatic metric drift.
Added 12 headless tests including display selection and tier projection methods.
"""
writes = {preview: encode(text, raw_preview), model: encode(MODEL_TEXT, raw_model),
          test: TEST_TEXT.encode(), history: history_text.encode()}
source = root / "data_authoring/source"
before = {p: p.read_bytes() for p in source.glob("*.csv")}

def rollback():
    for path, raw in originals.items():
        if raw is None: path.unlink(missing_ok=True)
        else: path.write_bytes(raw)
print("=== COPY FROM HERE ===", flush=True)
print("Backup folder:", backup, flush=True)
try:
    for path, raw in writes.items(): path.write_bytes(raw)
    suite = subprocess.run([sys.executable, "-m", "unittest", "discover", "-s", "tests"], cwd=work,
                           stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, errors="replace")
    print(suite.stdout, flush=True)
    if suite.returncode: raise RuntimeError("Full test suite failed")
    if set(source.glob("*.csv")) != set(before) or any(p.read_bytes() != raw for p, raw in before.items()):
        raise RuntimeError("Source CSV changes detected during tests; inspect them separately")
except BaseException:
    rollback()
    print("PATCH ROLLED BACK: prior preview/model restored; new test and history removed.", flush=True)
    raise
print("Source CSVs unchanged. Expected test total if baseline was 351: 363", flush=True)
print("RESULT: PASS. Restart Workbench and check metric controls and Activity Log.", flush=True)
